function hostUrl(u) { var m = String(u || '').trim().match(/^https?:\/\/([^\/?#:@]+)/i); return m ? m[1].toLowerCase() : ''; }

// Funding & Tenders: o arquivo de dados do tópico traz "description" e "conditions" (onde ficam as condições de elegibilidade).
function urlCondicoesUE(url) {
  var m = String(url || '').match(/^https:\/\/ec\.europa\.eu\/info\/funding-tenders\/opportunities\/portal\/screen\/opportunities\/topic-details\/([A-Za-z0-9-]+)\/?$/);
  if (!m || /^\d+COMPETITIVE_CALL/i.test(m[1])) return '';
  return 'https://ec.europa.eu/info/funding-tenders/opportunities/data/topicDetails/' + m[1].toLowerCase() + '.json';
}
// Texto (sem HTML) da descrição e das condições do tópico; '' se o JSON não vier no formato esperado.
function lerCondicoesUE(bruto) {
  var d;
  try { d = JSON.parse(String(bruto || '')); } catch (e) { return ''; }
  var t = d && (d.TopicDetails || d.topicDetails) || d;
  if (!t || typeof t !== 'object') return '';
  var limpo = function (h) { return decodeEnt(String(h || '').replace(/<(br|p|div|li|tr|h[1-6]|section|article|dt|dd)\b[^>]*>/gi, '\n').replace(/<[^>]+>/g, ' ')).replace(/[ \t\u00a0\ufeff]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim(); };
  var cond = limpo(t.conditions).replace(/^["'>\s]+/, '');
  if (!cond) return '';
  return ('Condições do tópico (General conditions, incluindo Eligible Countries):\n' + cond.slice(0, 7000) + '\n\nDescrição do tópico:\n' + limpo(t.description).slice(0, 2500));
}

function selecionarLote(linhas, fontes, o) {
  var limite = (o && o.limite) || LIMITE_LOTE, manual = !!(o && o.manual);
  var porNome = {};
  (fontes || []).forEach(function (f) { if (f && f.nome) porNome[f.nome] = f; });
  var cands = [];
  (linhas || []).forEach(function (r) {
    if (!r || !r.id || !r.url || !enderecoPublico(r.url)) return;
    var t = Number(r.tentativas) || 0;
    if (!(r.situacao_triagem === 'pendente' || (r.situacao_triagem === 'erro' && t < 3))) return;
    if (/^\s*\[TESTE\]/i.test(String(r.titulo || '')) && !manual) return;
    cands.push(r);
  });
  cands.sort(function (a, b) { return String(a.createdAt).localeCompare(String(b.createdAt)); });
  var porFonte = {};
  cands.forEach(function (r) { (porFonte[r.fonte] = porFonte[r.fonte] || []).push(r); });
  var filas = Object.keys(porFonte).sort().map(function (k) { return porFonte[k]; });
  var escolhidos = [];
  while (escolhidos.length < limite && filas.some(function (f) { return f.length; })) {
    filas.forEach(function (f) { if (f.length && escolhidos.length < limite) escolhidos.push(f.shift()); });
  }
  return escolhidos.map(function (r) {
    var f = porNome[r.fonte] || {};
    var tipo = f.tipo || 'html';
    // ue: o portal é montado por JavaScript, sem texto útil; lê-se o arquivo de dados do tópico (condições de elegibilidade).
    // Sem identificador reconhecível no endereço, o texto da coleta é tudo o que há.
    var urlUe = tipo === 'ue' ? urlCondicoesUE(r.url) : '';
    var busca = tipo === 'ue' && !urlUe ? 'sem_pagina' : 'buscar';
    return {
      situacao_anterior: r.situacao_triagem, id: r.id, chave: r.chave, url: r.url, titulo: r.titulo, fonte: r.fonte,
      tentativas: Number(r.tentativas) || 0, tipo_fonte: tipo, abrangencia_fonte: f.abrangencia || 'nacional',
      prazo_fonte: dataIso(r.prazo_fonte) || null, texto_fonte: String(r.texto_fonte || ''), tipo_busca: busca,
      req_url: tipo === 'transferegov' ? r.url + (r.url.indexOf('?') >= 0 ? '&' : '?') + 'uf_programa=DF&tamanho_da_pagina=200' : (urlUe || r.url)
    };
  });
}

// ---------- texto da página ----------
function htmlParaTexto(html, base) {
  var h = String(html || '');
  h = h.replace(/<(script|style|noscript|svg)\b[\s\S]*?<\/\1>/gi, ' ');
  h = h.replace(/<(nav|header|footer)\b[\s\S]*?<\/\1>/gi, ' ');
  var links = [], vistos = {};
  h.replace(/<a\b[^>]*href\s*=\s*"([^"]+)"[^>]*>([\s\S]*?)<\/a>/gi, function (m, href, txt) {
    var u = resolveUrl(decodeEnt(href), base); if (!u) return m;
    var t = decodeEnt(txt.replace(/<[^>]+>/g, ' ')).replace(/\s+/g, ' ').trim();
    if (/(edital|anexo|chamamento|chamada|\.pdf|-pdf|inscri|regulamento|selec|call|guidelines|apply)/i.test(u + ' ' + t) && !vistos[u] && links.length < 40) { vistos[u] = 1; links.push('- ' + (t || 'link') + ': ' + u); }
    return m;
  });
  var t = h.replace(/<(br|p|div|li|tr|h[1-6]|section|article|dt|dd)\b[^>]*>/gi, '\n').replace(/<[^>]+>/g, ' ');
  t = decodeEnt(t).replace(/[ \t]+/g, ' ').replace(/\n\s*\n+/g, '\n').trim();
  return { texto: t, links: links };
}
function unicos(a) { return a.filter(function (v, i, arr) { return v && arr.indexOf(v) === i; }); }

// Transferegov (API por id_programa, só linhas do DF): a qualificação de cada linha diz quem pode propor.
// "Proposta Voluntária" = qualquer proponente da natureza indicada, prazo em dt_prog_*_receb_prop.
// Emenda parlamentar e proponente específico do concedente ficam fora. chamamento_projeto = SIM indica chamamento público.
// "Organização da Sociedade Civil" é a natureza em que o Modal (ICT privada sem fins lucrativos) se encaixa.
var NATUREZA_MODAL = /(sociedade civil|sem fins lucrativos|privada)/i;
function lerTransferegov(lista) {
  var p = lista[0] || {};
  var vol = lista.filter(function (x) { return String(x.qualificacao_proposta || '').split(',').map(function (s) { return s.trim(); }).indexOf('Proposta Voluntária') >= 0; });
  var volOsc = vol.filter(function (x) { return NATUREZA_MODAL.test(String(x.natureza_juridica_programa || '')); });
  var volOscDf = volOsc.filter(function (x) { return x.uf_programa === 'DF'; });
  var fins = unicos(volOscDf.map(function (x) { return dataIso(x.dt_prog_fim_receb_prop); })).sort();
  var tg = {
    qualificacoes: unicos(lista.map(function (x) { return x.qualificacao_proposta; })),
    naturezas: unicos(lista.map(function (x) { return x.natureza_juridica_programa; })),
    voluntaria: vol.length > 0,
    voluntaria_osc: volOsc.length > 0,
    voluntaria_osc_df: volOscDf.length > 0,
    chamamento: volOsc.some(function (x) { return x.chamamento_projeto === 'SIM'; }),
    prazo: fins.length ? fins[fins.length - 1] : '',
    situacao: String(p.sit_programa || ''),
    codigo: String(p.cod_programa || '')
  };
  var ref = volOscDf[0] || volOsc[0] || p;
  var texto = [
    'Programa federal no Transferegov (transferência discricionária com envio de propostas pelo Transferegov)',
    'Programa: ' + p.nome_programa,
    'Código: ' + p.cod_programa,
    'Órgão: ' + p.desc_orgao_sup_programa + ' / ' + p.orgao_executor,
    'Situação: ' + p.sit_programa,
    'Qualificação das propostas aceitas: ' + tg.qualificacoes.join('; '),
    'Natureza jurídica de quem pode propor: ' + tg.naturezas.join('; '),
    'Propostas voluntárias de organização da sociedade civil do DF: ' + (tg.voluntaria_osc_df ? 'aceitas' : 'não aceitas'),
    'Recebimento de propostas voluntárias: de ' + (ref.dt_prog_ini_receb_prop || 'não informado') + ' até ' + (ref.dt_prog_fim_receb_prop || 'não informado'),
    'Chamamento público: ' + (tg.chamamento ? 'SIM' : 'NÃO'),
    'Modalidade: ' + p.modalidade_programa,
    'Descrição: ' + p.descricao,
    'Observação: ' + p.observacao,
    'Critérios de seleção: ' + p.criterios_de_selecao
