    voluntaria_osc_df: volOscDf.length > 0,
    chamamento: volOsc.some(function (x) { return x.chamamento_projeto === 'SIM'; }),
    prazo: fins.length ? fins[fins.length - 1] : '',
    situacao: String(p.sit_programa || ''),
    codigo: String(p.cod_programa || '')
  };
  var ref = volOscDf[0] || volOsc[0] || p;
  var texto = [
    'Programa federal no Transferegov (transferência discricionária com envio de propostas pelo Transferegov)',
    'Programa: ' + p.nome_programa,
    'Código: ' + p.cod_programa,
    'Órgão: ' + p.desc_orgao_sup_programa + ' / ' + p.orgao_executor,
    'Situação: ' + p.sit_programa,
    'Qualificação das propostas aceitas: ' + tg.qualificacoes.join('; '),
    'Natureza jurídica de quem pode propor: ' + tg.naturezas.join('; '),
    'Propostas voluntárias de organização da sociedade civil do DF: ' + (tg.voluntaria_osc_df ? 'aceitas' : 'não aceitas'),
    'Recebimento de propostas voluntárias: de ' + (ref.dt_prog_ini_receb_prop || 'não informado') + ' até ' + (ref.dt_prog_fim_receb_prop || 'não informado'),
    'Chamamento público: ' + (tg.chamamento ? 'SIM' : 'NÃO'),
    'Modalidade: ' + p.modalidade_programa,
    'Descrição: ' + p.descricao,
    'Observação: ' + p.observacao,
    'Critérios de seleção: ' + p.criterios_de_selecao
  ].join('\n');
  return { texto: texto, tg: tg };
}

// Junta o texto guardado na coleta com o que a leitura da página trouxe. resp: item do nó de leitura (texto, PDF, erro ou nada).
function prepararTexto(op, resp, hoje, areas) {
  resp = resp || {};
  var texto = '', links = [], ehPdf = false, tg = null, erroPagina = '';
  if (resp.error) erroPagina = String(resp.error.message || resp.error.description || JSON.stringify(resp.error));
  var ueComPagina = op.tipo_fonte === 'ue' && op.tipo_busca !== 'sem_pagina';
  if (typeof resp.text === 'string') { ehPdf = true; texto = resp.text; }
  else if (op.tipo_busca !== 'sem_pagina' && !erroPagina) {
    var bruto = resp.data;
    if (bruto && typeof bruto !== 'string') bruto = JSON.stringify(bruto);
    bruto = bruto || '';
    if (/^\s*"/.test(bruto)) { try { bruto = JSON.parse(bruto); } catch (e) {} }
    if (op.tipo_fonte === 'ue') {
      texto = lerCondicoesUE(bruto);
      if (!texto) erroPagina = 'condições do tópico da UE ilegíveis';
    } else if (op.tipo_fonte === 'transferegov') {
      try { var d = JSON.parse(bruto); var r = lerTransferegov(d.data || []); texto = r.texto; tg = r.tg; } catch (e) { texto = ''; tg = null; }
    } else {
      var h = htmlParaTexto(bruto, op.url);
      texto = h.texto; links = h.links;
    }
  }
  var base = String(op.texto_fonte || '');
  // Transferegov: o texto vem da API (fatos estruturados); nos demais, o texto da coleta vai primeiro e a página completa depois.
  var junto = tg ? texto : (base && texto ? base + '\n\n' + (op.tipo_fonte === 'ue' ? '--- CONDIÇÕES DO TÓPICO ---' : '--- PÁGINA ---') + '\n' + texto : (base || texto));
  junto = String(junto || '').slice(0, 19000);
  var erro = '';
  // UE com condições do tópico a ler: sem elas não há como confirmar se o Brasil recebe recursos; conta como falha da tentativa (volta no lote seguinte).
  if (ueComPagina && !tg && !texto) erro = 'falha ao ler as condições do tópico da UE: ' + (erroPagina || 'resposta vazia');
  else if (junto.replace(/\s+/g, '').length < 150) erro = erroPagina ? 'falha ao ler a página: ' + erroPagina : (ehPdf ? 'PDF sem texto legível (talvez digitalizado)' : 'conteúdo vazio ou ilegível');
  if (op.tipo_fonte === 'transferegov' && !tg && !erro) erro = 'resposta do Transferegov ilegível';
  return { texto_tamanho: junto.length, eh_pdf: ehPdf, erro_leitura: erro.slice(0, 300), prompt: erro ? '' : montarPrompt(op, junto, links, ehPdf, tg, hoje, areas), tg: tg, texto_lido: erro ? '' : junto };
}

// ---------- IA ----------
var SISTEMA = 'Você faz a triagem de oportunidades de recursos (editais, chamadas, programas) para o Instituto Modal, uma Instituição Científica, Tecnológica e de Inovação (ICT) privada, associação sem fins lucrativos, sediada em Brasília-DF desde 2017. O Modal NÃO é OSCIP. Leia o conteúdo e extraia os dados pedidos com fidelidade ao texto. Não invente datas, valores nem números; deixe vazio o que não aparecer.';

function montarPrompt(op, texto, links, ehPdf, tg, hoje, areas) {
  var notaTg = tg ? '- Programa do Transferegov: um programa aberto a propostas voluntárias, mesmo sem chamamento público, conta como oportunidade (eh_oportunidade true) se entidade privada sem fins lucrativos puder cadastrar proposta. Em publico_elegivel, descreva quem pode propor segundo a descrição do programa (não só a natureza jurídica); se a descrição restringir o programa a um tipo específico de entidade, diga isso e responda papel_modal nao_elegivel.\n' : '';
  var internacional = op.abrangencia_fonte === 'internacional';
  return 'Hoje é ' + hoje + '. Analise o conteúdo abaixo, obtido de ' + op.url + ' (fonte: ' + op.fonte + '; título na coleta: "' + op.titulo + '").\n\n' +
    'Perfil do Modal: ICT privada sem fins lucrativos (associação), Brasília-DF. Áreas de atuação:\n' + areas.map(function (a) { return '- ' + a; }).join('\n') + '\n\n' +
    'Preencha os campos pedidos, em português, sem inventar. Regras:\n' +
    '- eh_oportunidade: true só se o conteúdo for um edital, chamada, chamamento, seleção, programa com inscrições, credenciamento ou programa com envio de propostas, ao qual uma instituição possa se candidatar (ou a página oficial dele). Notícias, resultados, atas, páginas institucionais, licitação de compra ou serviço, prêmio sem repasse de recursos e bolsa individual NÃO são; explique em motivo_nao.\n' +
    notaTg +
    '- situacao: aberto (inscrições abertas hoje ou que ainda vão abrir), encerrado (prazo já passou ou seleção em resultado ou execução) ou indefinido.\n' +
    '- prazo: data final de inscrição ou envio de propostas, AAAA-MM-DD; vazio se não houver.\n' +
    '- numero_edital: número oficial como aparece (ex.: Edital nº 05/2026, Chamada 12/2026); vazio se não houver.\n' +
    '- publico_elegivel: quem pode concorrer, em uma frase.\n' +
    '- papel_modal: proponente se ICT, instituição de pesquisa, entidade sem fins lucrativos ou associação pode propor diretamente; parceira se quem propõe é empresa e o edital exige ou admite ICT parceira ou executora; nao_elegivel se só órgãos públicos, empresas sem espaço para ICT, pessoas físicas, instituições de ensino específicas ou outro público que exclua o Modal; indefinido se não der para saber.\n' +
    '- exige_oscip: true só se o edital exigir que o proponente seja OSCIP (Organização da Sociedade Civil de Interesse Público).\n' +
    '- regiao: abrangência geográfica. abrange_df: sim se inclui o Distrito Federal ou é nacional; nao se restrito a outros lugares; indefinido.\n' +
    (internacional ? '- papel_modal em fonte internacional: proponente só se o texto disser expressamente que organização brasileira (ou de país terceiro) pode coordenar ou propor sozinha; se o Brasil só puder entrar como parceiro de consórcio liderado por entidade local, responda parceira.\n' : '') +
    (internacional ? '- aceita_brasil: esta fonte é internacional. sim SOMENTE se o texto disser de forma explícita que organização brasileira (ou de país terceiro, de país em desenvolvimento ou da América Latina) pode receber recursos ou coordenar; nao se o Brasil é inelegível ou só participa sem financiamento; indefinido se o texto não disser (remeter a um anexo geral, como "Annex B" do Horizon Europe, NÃO é dizer: países como o Brasil não recebem financiamento automaticamente). Muitas chamadas exigem proponente com sede ou filial local, ou vínculo com organização local.\n- evidencia_brasil: em fonte internacional, o trecho copiado LITERALMENTE do conteúdo (de 20 a 300 caracteres) que diz que organização brasileira ou de país terceiro pode receber recursos ou coordenar; vazio se não houver. Não parafraseie nem invente.\n' : '- aceita_brasil: sim, a menos que o texto diga o contrário.\n- evidencia_brasil: deixe vazio.\n') +
    '- valor: valor total ou por projeto como aparece; vazio se não houver.\n' +
    '- temas: até 6 temas curtos (o primeiro é o tema central).\n' +
    '- areas_modal: no máximo 3 áreas da lista acima, só as que descrevem o OBJETO CENTRAL do edital (não o que o Modal poderia fazer nele), copiadas exatamente como estão; [] se nenhuma. Edital genérico de CT&I ou de formação sem tema definido recebe só a área genérica correspondente.\n' +
    '- link_edital_oficial: endereço do edital oficial (PDF ou página) se aparecer; senão ' + op.url + '.\n' +
    '- ha_recurso: sim se quem for selecionado recebe recursos financeiros ou apoio material (fomento, subvenção, doação, financiamento); nao se é só credenciamento, cooperação técnica sem recursos, cadastro ou parceria sem repasse; indefinido.\n' +
    '- data_publicacao: data da publicação ou da última retificação, AAAA-MM-DD; vazio se não houver.\n' +
    '- resumo: 2 a 3 frases sobre o que financia e para quem.\n\n' +
    'CONTEÚDO' + (ehPdf ? ' (PDF)' : '') + ':\n' + texto + (links.length ? '\n\nLINKS NA PÁGINA:\n' + links.join('\n') : '');
}

var ESQUEMA_IA = {
  type: 'object',
  properties: {
    eh_oportunidade: { type: 'boolean' }, motivo_nao: { type: 'string' }, ofertante: { type: 'string' }, titulo_oficial: { type: 'string' },
    numero_edital: { type: 'string' }, tipo_instrumento: { type: 'string' }, publico_elegivel: { type: 'string' },
    papel_modal: { type: 'string', enum: ['proponente', 'parceira', 'nao_elegivel', 'indefinido'] },
    exige_oscip: { type: 'boolean' }, regiao: { type: 'string' },
    abrange_df: { type: 'string', enum: ['sim', 'nao', 'indefinido'] },
    aceita_brasil: { type: 'string', enum: ['sim', 'nao', 'indefinido'] },
    evidencia_brasil: { type: 'string', description: 'trecho literal do conteúdo; vazio se não houver' },
    prazo: { type: 'string', description: 'AAAA-MM-DD ou vazio' }, valor: { type: 'string' },
    temas: { type: 'array', items: { type: 'string' } }, areas_modal: { type: 'array', items: { type: 'string' } },
    link_edital_oficial: { type: 'string' }, resumo: { type: 'string' },
    situacao: { type: 'string', enum: ['aberto', 'encerrado', 'indefinido'] },
    ha_recurso: { type: 'string', enum: ['sim', 'nao', 'indefinido'] },
    data_publicacao: { type: 'string', description: 'AAAA-MM-DD ou vazio' }
  },
  required: ['eh_oportunidade', 'motivo_nao', 'ofertante', 'titulo_oficial', 'numero_edital', 'tipo_instrumento', 'publico_elegivel', 'papel_modal', 'exige_oscip', 'regiao', 'abrange_df', 'aceita_brasil', 'evidencia_brasil', 'prazo', 'valor', 'temas', 'areas_modal', 'link_edital_oficial', 'resumo', 'situacao', 'ha_recurso', 'data_publicacao']
};

// Valida a saída da IA contra o esquema: tipos e enums; o que fugir vira o valor neutro. Devolve null se não for objeto.
function normalizarIA(ia) {
  if (!ia || typeof ia !== 'object' || Array.isArray(ia) || !('eh_oportunidade' in ia)) return null;
  var enums = function (v, ok, neutro) { v = String(v || '').toLowerCase().trim(); return ok.indexOf(v) >= 0 ? v : neutro; };
  var str = function (v) { return v === undefined || v === null ? '' : String(v).trim(); };
  var lista = function (v) { return Array.isArray(v) ? v.map(str).filter(Boolean) : (v ? String(v).split(/[,;]/).map(str).filter(Boolean) : []); };
  var bool = function (v) { return v === true || String(v).toLowerCase() === 'true'; };
  return {
    eh_oportunidade: bool(ia.eh_oportunidade), motivo_nao: str(ia.motivo_nao), ofertante: str(ia.ofertante), titulo_oficial: str(ia.titulo_oficial),
    numero_edital: str(ia.numero_edital), tipo_instrumento: str(ia.tipo_instrumento), publico_elegivel: str(ia.publico_elegivel),
    papel_modal: enums(ia.papel_modal, ['proponente', 'parceira', 'nao_elegivel', 'indefinido'], 'indefinido'),
    exige_oscip: bool(ia.exige_oscip), regiao: str(ia.regiao),
    abrange_df: enums(ia.abrange_df, ['sim', 'nao', 'indefinido'], 'indefinido'),
    aceita_brasil: enums(ia.aceita_brasil, ['sim', 'nao', 'indefinido'], 'indefinido'), evidencia_brasil: str(ia.evidencia_brasil),
    prazo: /^\d{4}-\d{2}-\d{2}$/.test(str(ia.prazo)) ? str(ia.prazo) : '', valor: str(ia.valor),
    temas: lista(ia.temas), areas_modal: lista(ia.areas_modal), link_edital_oficial: str(ia.link_edital_oficial), resumo: str(ia.resumo),
    situacao: enums(ia.situacao, ['aberto', 'encerrado', 'indefinido'], 'indefinido'),
    ha_recurso: enums(ia.ha_recurso, ['sim', 'nao', 'indefinido'], 'indefinido'),
    data_publicacao: /^\d{4}-\d{2}-\d{2}$/.test(str(ia.data_publicacao)) ? str(ia.data_publicacao) : ''
  };
}

// ---------- regras ----------
var REG_OK = /(nacional|brasil|todo o pais|todos os estados|todas as ufs|distrito federal|\bdf\b|brasilia|centro oeste|ride)/;
var NAO_OPORTUNIDADE_TIPO = /^(preg[aã]o|licita[cç][aã]o|concorr[eê]ncia|tomada de pre[cç]os|dispensa de licita|inexigibilidade|bolsas?\b)/i;
// Tema central fora do escopo: olha o título oficial e os dois primeiros temas (o primeiro é o central).
var FORA_TEMA = /(assist[eê]ncia social|sa[uú]de assistencial|aten[cç][aã]o b[aá]sica|\bcultur(a|al|ais)\b|\bespor(te|tes|tivo|tivos|tiva|tivas)\b|fundo (da|do|municipal|estadual) (crian[cç]a|idoso)|\bcrian[cç]as?\b|\bidosos?\b|pessoa idosa|adolescente)/i;

function descartar(motivo) { return { situacao: 'descartada', motivo: motivo }; }

// Aplica as regras na ordem do contrato; devolve { situacao, motivo }. Cada descarte tem motivo legível em português.
function decidir(o) {
  var ia = o.ia, tg = o.tg || null, hoje = o.hoje, areas = o.areas;
  var prazoFonte = dataIso(o.op.prazo_fonte);
  var prazo = prazoFonte || (tg && dataIso(tg.prazo)) || ia.prazo || '';
  var internacional = o.op.abrangencia_fonte === 'internacional';
  var regiao = norm(ia.regiao);
  var instrumento = semAcento(ia.tipo_instrumento).trim();
  if (tg) {
    if (!tg.voluntaria) return descartar('Programa do Transferegov sem proposta voluntária (aceita só: ' + (tg.qualificacoes || []).join('; ') + '); emenda parlamentar e proponente específico do concedente ficam fora');
    if (!tg.voluntaria_osc) return descartar('Programa do Transferegov não aceita proposta voluntária de entidade privada sem fins lucrativos (natureza jurídica: ' + (tg.naturezas || []).join('; ') + ')');
    if (!tg.voluntaria_osc_df) return descartar('Abrangência não inclui o DF: o programa não aceita proposta voluntária de entidade privada sem fins lucrativos do DF');
    if (tg.situacao && tg.situacao !== 'DISPONIBILIZADO') return descartar('Programa não está disponível no Transferegov (situação ' + tg.situacao + ')');
  } else {
    if (ia.eh_oportunidade !== true) return descartar('Não é oportunidade de recursos: ' + (ia.motivo_nao || 'página sem chamada, edital ou programa aberto a propostas'));
    if (NAO_OPORTUNIDADE_TIPO.test(instrumento)) return descartar('Não é oportunidade de recursos: ' + (/^bolsa/i.test(instrumento) ? 'bolsa individual' : 'licitação de compra ou serviço') + ' (' + ia.tipo_instrumento + ')');
    if (ia.situacao === 'encerrado') return descartar('Encerrada' + (prazo ? ' (prazo ' + prazo + ')' : ''));
  }
  if (prazo && prazo < hoje) return descartar('Prazo vencido em ' + prazo);
  if (ia.papel_modal === 'nao_elegivel') return descartar('O Modal não é elegível: ' + (ia.publico_elegivel || 'público não informado'));
  if (ia.exige_oscip === true) return descartar('Exige que o proponente seja OSCIP; o Modal não é OSCIP');
  if (!internacional) {
    if (ia.abrange_df === 'nao' || (ia.abrange_df !== 'sim' && regiao && !REG_OK.test(regiao))) return descartar('Abrangência não inclui o DF nem é nacional: ' + (ia.regiao || 'não informada'));
  } else if (ia.aceita_brasil === 'nao') {
    return descartar('Fonte internacional que não aceita proponente do Brasil');
  } else if (!evidenciaBrasilValida(ia, o.texto)) {
    // Decisão de 25/11/2026: só entra o que o texto lido diz expressamente; "indefinido" e trecho que não está no texto não passam.
    return descartar('Internacional sem evidência de que organização brasileira pode receber recursos (exige sede na Europa ou vínculo com organização local)');
  }
  if (ia.ha_recurso === 'nao') return descartar('Sem recursos para a instituição (não há repasse nem apoio financeiro ou material)');
  var anoNumero = (function () { var m = String(ia.numero_edital || '').match(/(?:\/|\b)(20\d{2})\b/); return m ? m[1] : ''; })();
  var lim = new Date(hoje + 'T00:00:00Z'); lim.setUTCMonth(lim.getUTCMonth() - 12);
  var limite = lim.toISOString().slice(0, 10);
  var antigo = ia.data_publicacao ? ia.data_publicacao < limite : (anoNumero && Number(anoNumero) < Number(limite.slice(0, 4)));
  if (!prazo && antigo) return descartar('Sem prazo e publicada há mais de 12 meses (' + (ia.data_publicacao || anoNumero) + '): provavelmente encerrada');
  if (!o.areasValidas.length) return descartar('Nenhuma área de atuação do Modal (temas: ' + (ia.temas.join(', ') || 'não informados') + ')');
  var central = [ia.titulo_oficial].concat(ia.temas.slice(0, 2)).join(' | ');
  if (FORA_TEMA.test(semAcento(central).replace(/ç/g, 'c'))) return descartar('Tema central fora do escopo do Modal (assistência social, saúde assistencial, cultura, esporte, criança ou idoso): ' + central);
  return { situacao: 'aprovada', motivo: '' };
}

// aceita_brasil = 'sim' E trecho citado não vazio E presente no texto lido (conferência de trecho, sem acento, caixa nem pontuação).
function evidenciaBrasilValida(ia, texto) {
  var tr = norm(ia.evidencia_brasil);
  return ia.aceita_brasil === 'sim' && tr.length >= 20 && norm(texto).indexOf(tr) >= 0;
}
// Em fonte internacional, 'proponente' só vale quando o trecho citado diz que organização brasileira ou de país terceiro coordena ou propõe; senão, parceira de consórcio.
var COORDENA = /(coordinat|\blead(s|er|ers|ing)?\b|may (apply|submit|propose)|can (apply|submit|propose)|coorden|propon|submeter)/i;
function papelFinal(o, ia) {
  if (o.op.abrangencia_fonte !== 'internacional' || ia.papel_modal !== 'proponente') return ia.papel_modal;
  return COORDENA.test(ia.evidencia_brasil) ? 'proponente' : 'parceira';
}

function classificarAbrangencia(o) {
  if (o.op.abrangencia_fonte === 'internacional') return 'internacional';
  var r = norm(o.ia.regiao);
  if (/(nacional|brasil|todo o pais|todos os estados|todas as ufs)/.test(r)) return 'nacional';
  if (/(distrito federal|\bdf\b|brasilia)/.test(r)) return 'DF';
  return o.op.abrangencia_fonte === 'DF' ? 'DF' : 'nacional';
}

// Entrada: { op, ia (saída bruta), tg, hoje, agoraIso, areas (lista da planilha), aprovadas (linhas já aprovadas) }
// Saída: { linha, principal }  (principal = linha da aprovada que recebeu endereço alternativo ou retificação)
function aplicarRegras(o) {
  var ia = normalizarIA(o.ia);
  if (!ia) throw new Error('saída da IA inválida');
  var op = o.op, tg = o.tg || null, hoje = o.hoje;
  var areasValidas = validarAreas(ia.areas_modal, o.areas);
  var d = decidir({ op: op, ia: ia, tg: tg, hoje: hoje, areas: o.areas, areasValidas: areasValidas, texto: o.texto || '' });
  var situacao = d.situacao, motivo = d.motivo;
  var prazo = dataIso(op.prazo_fonte) || (tg && dataIso(tg.prazo)) || ia.prazo || '';
  // Programa do Transferegov aberto a propostas voluntárias e sem chamamento: "programa_aberto"; o resto é "edital".
  var tipoOp = tg && tg.voluntaria_osc && !tg.chamamento ? 'programa_aberto' : 'edital';
  if (situacao === 'aprovada' && tipoOp === 'programa_aberto') motivo = 'Programa aberto a propostas voluntárias, sem seleção (Transferegov)';

  var ofert = normOfertante(ia.ofertante);
  var numero = ia.numero_edital;
  var numNorm = numero ? normNumero(numero) : '';
  var tituloOficial = ia.titulo_oficial || op.titulo || '';
  var identidade = numNorm ? ofert + '|' + numNorm : norm(tituloOficial) + '|' + prazo;

  var duplicataDe = '', principal = null;
  if (situacao === 'aprovada') {
    var aprov = (o.aprovadas || []).filter(function (r) { return r && r.chave && r.chave !== op.chave && r.situacao_triagem === 'aprovada'; });
    var p = null, porNumero = false;
    if (numNorm) { p = aprov.find(function (r) { return r.identidade && r.identidade === identidade; }) || null; porNumero = !!p; }
    if (!p) p = aprov.find(function (r) { return !numNorm && r.identidade && r.identidade === identidade; }) || null;
    if (!p) p = aprov.find(function (r) { return ofert && normOfertante(r.ofertante) === ofert && jaccard(r.titulo_oficial || r.titulo, tituloOficial) >= 0.8 && dataIso(r.prazo) === prazo; }) || null;
    if (p) {
      situacao = 'duplicata'; duplicataDe = p.chave;
      motivo = 'Mesmo edital já aprovado: ' + (p.titulo_oficial || p.titulo) + ' (' + p.url + ')';
      var alt = String(p.enderecos_alternativos || '').split('\n').filter(Boolean);
      if (alt.indexOf(op.url) < 0 && p.url !== op.url) alt.push(op.url);
      var cols = { enderecos_alternativos: alt.join('\n') };
      var prazoP = dataIso(p.prazo);
      var mudouPrazo = prazo && prazoP && prazo !== prazoP;
      var mudouValor = ia.valor && p.valor && digitos(ia.valor) && digitos(ia.valor) !== digitos(p.valor);
      // Retificação só altera a principal quando vem da mesma fonte e do mesmo site: uma página de terceiro não muda prazo nem valor.
      if (porNumero && p.fonte === op.fonte && hostUrl(p.url) && hostUrl(p.url) === hostUrl(op.url) && (mudouPrazo || mudouValor)) {
        if (mudouPrazo) cols.prazo = isoDoDia(prazo);
        if (mudouValor) cols.valor = ia.valor;
        cols.motivo = ((p.motivo ? p.motivo + ' | ' : '') + 'atualizada por retificação em ' + hoje + (mudouPrazo ? ' (prazo ' + prazoP + ' -> ' + prazo + ')' : '') + (mudouValor ? ' (valor ' + p.valor + ' -> ' + ia.valor + ')' : '')).slice(0, 500);
        motivo += '; trouxe retificação aplicada à principal';
      }
      principal = { chave: p.chave, cols: cols, retificada: !!(cols.prazo || cols.valor) };
    }
  }
  var aprovadaOuDup = situacao !== 'descartada';
  var linha = {
    situacao_triagem: situacao,
    motivo: String(motivo).slice(0, 500),
    ofertante: ia.ofertante.slice(0, 300),
    titulo_oficial: tituloOficial.slice(0, 400),
    numero_edital: numero.slice(0, 120),
    identidade: identidade.slice(0, 400),
    duplicata_de: duplicataDe,
    tipo_instrumento: ia.tipo_instrumento.slice(0, 200),
    tipo_oportunidade: tipoOp,
    publico_elegivel: ia.publico_elegivel.slice(0, 500),
    papel_modal: papelFinal(o, ia),
    regiao: ia.regiao.slice(0, 200),
    abrangencia: classificarAbrangencia({ op: op, ia: ia }),
    prazo: isoDoDia(prazo),
    valor: ia.valor.slice(0, 200),
    temas: ia.temas.join(', ').slice(0, 300),
    areas_modal: aprovadaOuDup ? areasValidas.join('; ').slice(0, 500) : '',
    link_edital_oficial: ((enderecoPublico(ia.link_edital_oficial) ? ia.link_edital_oficial : '') || op.url).slice(0, 1000),
    resumo: ia.resumo.slice(0, 1200),
    triagem_em: o.agoraIso,
    tentativas: op.tentativas || 0
  };
  return { linha: linha, principal: principal };
}

// Falha de leitura ou da IA: conta a tentativa; depois de 3 a linha deixa de ser selecionada.
function registrarErro(op, resp, agoraIso) {
  resp = resp || {};
